import type React from 'react'
import {NinetailedProvider} from '@ninetailed/experience.js-react'
import type {Locale} from '@ninetailed/experience.js-shared'

import {NinetailedPageTracker} from './NinetailedPageTracker'

interface NinetailedWrapperProps {
  clientId: string
  environment: string
  /** ISO 639-1 language code (e.g., 'en', 'es', 'fr') - already converted by App.tsx */
  locale: string
  children: React.ReactNode
}

export default function NinetailedWrapper({clientId, environment, locale, children}: NinetailedWrapperProps) {
  return (
    <NinetailedProvider clientId={clientId} environment={environment} locale={locale as Locale}>
      <NinetailedPageTracker />
      {children}
    </NinetailedProvider>
  )
}
