import {useNinetailed} from '@ninetailed/experience.js-react'
import {useEffect} from 'react'

/**
 * Component to track page views with Ninetailed.
 * Must be rendered inside NinetailedProvider to access the tracking context.
 *
 * This component sends a page() event to Ninetailed on mount, which is required
 * for the React SDK to evaluate campaigns and show personalized content.
 *
 * @example
 * ```tsx
 * <NinetailedProvider {...config}>
 *   <NinetailedPageTracker />
 *   {children}
 * </NinetailedProvider>
 * ```
 */
export function NinetailedPageTracker() {
  const {page} = useNinetailed()

  useEffect(() => {
    // Send page view event on mount
    page()
  }, [page])

  return null
}
